import type Database from 'better-sqlite3'

/**
 * Migration runner. SQL files generated by drizzle-kit are bundled into the main-process build
 * (no files to locate at runtime) and applied in order inside a transaction each. A failed
 * migration throws; the application refuses to start on a partially migrated database.
 */
const files = import.meta.glob('./migrations/*.sql', { query: '?raw', import: 'default', eager: true }) as Record<
  string,
  string
>

export interface Migration {
  id: string
  sql: string
}

export const bundledMigrations: Migration[] = Object.entries(files)
  .map(([path, sql]) => ({ id: path.split('/').pop()!.replace(/\.sql$/, ''), sql }))
  .sort((a, b) => a.id.localeCompare(b.id))

export function pendingMigrations(sqlite: Database.Database, migrations = bundledMigrations): Migration[] {
  ensureTable(sqlite)
  const applied = new Set(
    (sqlite.prepare('SELECT id FROM __hmms_migrations').all() as { id: string }[]).map((r) => r.id)
  )
  return migrations.filter((m) => !applied.has(m.id))
}

export function runMigrations(sqlite: Database.Database, migrations = bundledMigrations): string[] {
  const pending = pendingMigrations(sqlite, migrations)
  const insert = sqlite.prepare('INSERT INTO __hmms_migrations (id, applied_at) VALUES (?, ?)')
  for (const m of pending) {
    const statements = m.sql
      .split('--> statement-breakpoint')
      .map((s) => s.trim())
      .filter(Boolean)
    const apply = sqlite.transaction(() => {
      for (const stmt of statements) sqlite.exec(stmt)
      insert.run(m.id, Date.now())
    })
    try {
      apply()
    } catch (err) {
      throw new Error(`Database migration ${m.id} failed: ${(err as Error).message}`)
    }
  }
  return pending.map((m) => m.id)
}

function ensureTable(sqlite: Database.Database): void {
  sqlite.exec('CREATE TABLE IF NOT EXISTS __hmms_migrations (id TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)')
}
